import {mean,finite,features,validateRows,normalizeRows,regressionMetrics,classificationMetrics,ruleScan,quantile} from './core.mjs?v=20261101-3';
export const MODELS=[
{id:'rules',name:'专家规则与CUSUM',en:'Rules + CUSUM',tag:'可解释预警',required:['oil','water','pressure'],target:'label',structure:['逐井时间排序','持续性 / 越限规则','残差累积 CUSUM','红黄蓝预警'],formula:'Sₜ = max(0, Sₜ₋₁ + zₜ − k)；连续3天产油低于前期基准15%',note:'规则阈值为PPT研究设定；仅形成待核实预警，不等于故障确诊。校准用训练集压力波动统计量。'},
{id:'arps',name:'Arps产量递减模型',en:'Arps DCA',tag:'数理基线',required:['oil'],target:'oil',structure:['单井产油 / 开井段','双曲 / 指数递减','网格最小二乘拟合','产油趋势与残差'],formula:'q(t) = qᵢ / (1 + bDᵢt)¹⁄ᵇ；b→0 时 q=qᵢexp(−Dᵢt)',note:'逐井拟合；只适用于相对稳定的递减阶段。关井和增产措施应分段分析。'},
{id:'crm',name:'电容电阻模型 CRM',en:'Lumped CRM',tag:'注采响应',required:['liquid','injection'],target:'liquid',structure:['注入 / 液量时序','指数响应记忆核','非负增益 + 初始响应','液量响应预测'],formula:'τ dq/dt + q = fI；qₜ = aqₜ₋₁ + f(1−a)Iₜ，a=exp(−Δt/τ)',note:'本版为恒井底压力假设下的单输入集总CRM；演示输入为油田总注水，不声称识别每对井真实连通系数。'},
{id:'tcn',name:'时序卷积网络 TCN',en:'Temporal CNN',tag:'生产趋势',required:features,target:'oil',structure:['8步 × 5维时序窗口','时序卷积16 / 核2','时序卷积8 / 核3','展平 → Dense16 → 产油'],formula:'ŷₜ₊₁ = fθ(Xₜ₋₇:ₜ)；L = MSE(y, ŷ)',note:'仅使用目标时刻之前的历史窗口。有效窗口少于24个时停止训练；不跨井构造窗口。'},
{id:'stgnn',name:'物理约束 GraphSAGE–TCN',en:'CRM-regularized STGNN',tag:'井组联合研判',required:features,target:'liquid',structure:['井节点 / 训练期相关图','邻井加权聚合 + 本井特征','共享卷积16 → 时序卷积8','液量预测 + CRM正则'],formula:'hᵥ = [xᵥ ∥ Σᵤ aᵥᵤxᵤ]；L = MSE(y,ŷ) + λ MSE(qCRM,ŷ)',note:'浏览器研究版：图由训练期产油相关性构建，并保留时间戳对齐；图权重不是因果连通系数。CRM正则不是完整多相渗流方程。'},
{id:'pinn',name:'压力扩散物理信息网络',en:'Pressure PINN',tag:'试井研究版',required:['x','t','pressure'],target:'pressure',structure:['归一化空间x / 时间t','Dense16 tanh','Dense16 tanh','压力 + 有限差分PDE残差'],formula:'∂u/∂t − α∂²u/∂x² = 0；L = Ldata + λ LPDE',note:'一维归一化压力扩散研究版。α为归一化扩散系数；用可微网络的中心差分约束内部点。需要实际坐标，不能从普通日生产表自动恢复真实压力场。'},
{id:'gdn',name:'图关联预测残差网络',en:'GDN-inspired detector',tag:'关联异常',required:features,target:'label',structure:['5变量训练相关图','邻域聚合 + 当前状态','Dense24 → Dense16 → 5维预测','标准化残差 / 分位数预警'],formula:'sₜ = mean|xₜ − x̂ₜ|；异常阈值 = Q₀.₉₉(s训练)',note:'GDN思想的简化实现，不是原论文完整架构。训练应使用确认正常的时段；无标签时只显示异常评分，不计算准确率。'},
{id:'diagnosis',name:'多标签异常融合诊断网络',en:'Multilabel MLP',tag:'根因辅助诊断',required:[...features,'root_cause'],target:'root_cause',structure:['生产 / 压力 / 注入特征','Dense24 ReLU','Dense12 ReLU','K类Sigmoid → 多标签原因'],formula:'pₖ = sigmoid(zₖ)；L = −Σ[yₖlogpₖ+(1−yₖ)log(1−pₖ)]',note:'必须上传现场确诊root_cause标签，多原因以|分隔。公开Volve无此标签，因此不会生成虚构确诊样本。输出为待专家审核的候选原因。'}];
export const inferenceRequired=id=>id==='arps'?[]:id==='crm'?['injection']:id==='pinn'?['x','t']:MODELS.find(m=>m.id===id).required.filter(k=>k!=='root_cause');
const day=r=>Date.parse(r.date)/86400000;
const ordered=rows=>[...rows].sort((a,b)=>String(a.well_id).localeCompare(String(b.well_id))||String(a.date).localeCompare(String(b.date)));
const group=rows=>Object.groupBy(ordered(rows),r=>r.well_id??'W');
const range=(n,fn)=>Array.from({length:n},(_,i)=>fn(i));
function arpsFit(rows){const params={};for(const [well,rs]of Object.entries(group(rows))){const a=rs.filter(r=>r.oil>0);if(a.length<4)continue;const origin=day(a[0]),span=Math.max(1,day(a.at(-1))-origin);let best={error:Infinity};for(let bi=0;bi<=10;bi++)for(let di=1;di<=70;di++){const b=bi/10,D=Math.exp(-8+di*.15)/span;const fs=a.map(r=>b===0?Math.exp(-D*(day(r)-origin)):(1+b*D*(day(r)-origin))**(-1/b));const qi=a.reduce((s,r,i)=>s+r.oil*fs[i],0)/fs.reduce((s,f)=>s+f*f,0);const error=mean(a.map((r,i)=>(qi*fs[i]-r.oil)**2));if(error<best.error)best={origin,b,D,qi,error};}params[well]=best;}if(!Object.keys(params).length)throw Error('每口井至少需要4条正产油记录');return params;}
function arpsPred(p,r){const t=Math.max(0,day(r)-p.origin);return p.qi*(p.b===0?Math.exp(-p.D*t):(1+p.b*p.D*t)**(-1/p.b));}
function crmFeatures(rs,tau,origin){let h=0;return rs.map((r,i)=>{const dt=i?Math.max(.01,day(r)-day(rs[i-1])):1,a=Math.exp(-dt/tau);h=a*h+(1-a)*Number(r.injection);return [h,Math.exp(-Math.max(0,day(r)-origin)/tau)];});}
function crmFit(rows){const params={};for(const [well,rs]of Object.entries(group(rows))){if(rs.length<4)continue;const origin=day(rs[0]);let best={error:Infinity};for(let ti=0;ti<40;ti++){const tau=Math.exp(-1+ti*.2),xs=crmFeatures(rs,tau,origin);let aa=0,ab=0,bb=0,ay=0,by=0;xs.forEach(([a,b],i)=>{aa+=a*a;ab+=a*b;bb+=b*b;ay+=a*rs[i].liquid;by+=b*rs[i].liquid;});const det=aa*bb-ab*ab;let f=det>1e-8?(ay*bb-by*ab)/det:0,q0=det>1e-8?(by*aa-ay*ab)/det:mean(rs.map(r=>r.liquid));f=Math.max(0,f);q0=Math.max(0,q0);const error=mean(xs.map(([a,b],i)=>(f*a+q0*b-rs[i].liquid)**2));if(error<best.error)best={tau,f,q0,origin,error};}params[well]=best;}if(!Object.keys(params).length)throw Error('每口井至少需要4条液量与注入记录');return params;}
function graphBuild(rows,keys,isSensor=false){if(isSensor){const matrix=keys.map(a=>keys.map(b=>Math.abs(corr(rows.map(r=>r[a]),rows.map(r=>r[b])))));return matrix.map((r,i)=>{const sorted=r.map((v,j)=>[v,j]).filter(x=>x[1]!==i).sort((a,b)=>b[0]-a[0]).slice(0,2);const s=sorted.reduce((s,x)=>s+x[0],0)||1;return r.map((v,j)=>sorted.some(x=>x[1]===j)?v/s:0);});}const g=group(rows),w=Object.keys(g),maps=Object.fromEntries(w.map(k=>[k,new Map(g[k].map(r=>[r.date,r.oil]))]));return Object.fromEntries(w.map(a=>{const others=w.filter(b=>b!==a).map(b=>{const common=[...maps[a].keys()].filter(t=>maps[b].has(t));return [b,common.length>5?Math.max(0,corr(common.map(t=>maps[a].get(t)),common.map(t=>maps[b].get(t)))):0];}).sort((a,b)=>b[1]-a[1]).slice(0,3);const sum=others.reduce((s,x)=>s+x[1],0);return [a,others.map(([b,v])=>[b,sum?v/sum:1/Math.max(1,others.length)])];}));}
function corr(a,b){const ma=mean(a),mb=mean(b);let n=0,aa=0,bb=0;for(let i=0;i<a.length;i++){const x=a[i]-ma,y=b[i]-mb;n+=x*y;aa+=x*x;bb+=y*y;}return aa*bb>1e-12?n/Math.sqrt(aa*bb):0;}
function scaleFit(rows,keys){return keys.map(k=>{const a=rows.map(r=>Number(r[k])),m=mean(a);return {m,s:Math.sqrt(mean(a.map(x=>(x-m)**2)))||1};});}
const scaled=(r,ks,sc)=>ks.map((k,i)=>(Number(r[k])-sc[i].m)/sc[i].s);
function augment(fit,rows){if(fit.id!=='stgnn')return rows;const map=new Map(rows.map(r=>[r.well_id+'@'+r.date,r]));return rows.map(r=>{const out={...r};for(const k of features){const available=(fit.graph[r.well_id]??[]).map(([w,a])=>[map.get(w+'@'+r.date),a]).filter(x=>x[0]);const total=available.reduce((s,x)=>s+x[1],0);out['n_'+k]=total?available.reduce((s,[v,a])=>s+a*Number(v[k]),0)/total:r[k];}return out;});}
function sequences(fit,rows){const inputs=[],targets=[],records=[];for(const rs of Object.values(group(augment(fit,rows))))for(let i=8;i<rs.length;i++){const history=rs.slice(i-8,i);if(history.some((r,j)=>j&&day(r)-day(history[j-1])!==1)||day(rs[i])-day(rs[i-1])!==1)continue;inputs.push(history.map(r=>scaled(r,fit.keys,fit.scale)));targets.push(Number(rs[i][fit.target]));records.push(rs[i]);}return {inputs,targets,records};}
function sensorInput(fit,r){const x=scaled(r,features,fit.scale);return [...x,...fit.graph.map(a=>a.reduce((s,w,i)=>s+w*x[i],0))];}
export async function trainModel(id,rows,val=[],options={},progress=()=>{}){const start=performance.now(),spec=MODELS.find(x=>x.id===id);if(!spec)throw Error('未知模型');rows=normalizeRows(rows);validateRows(rows,spec.required);if(rows.some(r=>!r.date||!r.well_id)&&!['pinn','diagnosis'].includes(id))throw Error('需要well_id和date字段');const fit={id,target:spec.target,trainedRows:rows.length,history:[],trainRows:rows,params:{}};if(id==='rules'){fit.params={decline:Number(options.decline)||15,water:3,pressure:Number(options.pressure)||.5,mu:mean(rows.map(r=>r.pressure)),sigma:Math.sqrt(mean(rows.map(r=>(r.pressure-mean(rows.map(x=>x.pressure)))**2)))||1};}
else if(id==='arps')fit.params=arpsFit(rows);
else if(id==='crm')fit.params=crmFit(rows);
else{const tf=globalThis.tf;if(!tf)throw Error('训练引擎未载入，请刷新页面或检查资源文件');await tf.ready();fit.keys=id==='pinn'?['x','t']:[...features];if(id==='stgnn'){if(Object.keys(group(rows)).length<2)throw Error('时空图模型至少需要2口具有同期生产资料的井');fit.graph=graphBuild(rows,features);fit.keys.push(...features.map(k=>'n_'+k));fit.crm=crmFit(rows);}
if(id==='gdn')fit.graph=graphBuild(rows,features,true);
fit.scale=scaleFit(augment(fit,rows),fit.keys);fit.yScale={m:mean(rows.map(r=>Number(r[fit.target])).filter(Number.isFinite)),s:1};if(!['gdn','diagnosis'].includes(id)){const ys=rows.map(r=>Number(r[fit.target]));fit.yScale.s=Math.sqrt(mean(ys.map(y=>(y-fit.yScale.m)**2)))||1;}
const model=tf.sequential(),epochs=Math.max(1,Math.min(150,Number(options.epochs)||20));let xs,ys,validation;
if(['tcn','stgnn'].includes(id)){const seq=sequences(fit,rows);if(seq.inputs.length<24)throw Error('至少需要24个连续日历史窗口（每井至少33天），请增加训练数据');xs=tf.tensor3d(seq.inputs);model.add(tf.layers.conv1d({inputShape:[8,fit.keys.length],filters:16,kernelSize:2,activation:'relu',padding:'valid'}));model.add(tf.layers.conv1d({filters:8,kernelSize:3,activation:'relu',padding:'valid'}));model.add(tf.layers.flatten());model.add(tf.layers.dense({units:16,activation:'relu'}));model.add(tf.layers.dense({units:1}));const normalize=y=>(y-fit.yScale.m)/fit.yScale.s;
if(id==='stgnn'){class TwinPrediction extends tf.layers.Layer{static className='TwinPrediction';computeOutputShape(s){return [s[0],2];}call(inputs){return tf.concat([inputs[0],inputs[0]],1);}getConfig(){return super.getConfig();}}if(!tf.serialization.SerializationMap.getMap().classNameMap.TwinPrediction)tf.serialization.registerClass(TwinPrediction);model.add(new TwinPrediction());const crmValues=crmPredict(fit.crm,rows,rows);const pm=new Map(crmValues.map(r=>[r.id,r.prediction]));ys=tf.tensor2d(seq.targets.map((y,i)=>[normalize(y),normalize(pm.get(seq.records[i].id)??y)]));fit.lambda=Number(options.lambda??.1);model.compile({optimizer:tf.train.adam(.003),loss:(y,p)=>tf.tidy(()=>p.slice([0,0],[-1,1]).sub(y.slice([0,0],[-1,1])).square().mean().add(p.slice([0,0],[-1,1]).sub(y.slice([0,1],[-1,1])).square().mean().mul(fit.lambda)))});}else{ys=tf.tensor2d(seq.targets.map(y=>[normalize(y)]));model.compile({optimizer:tf.train.adam(.003),loss:'meanSquaredError'});}if(val.length){validateRows(val,spec.required);const vs=sequences(fit,normalizeRows(val));if(vs.inputs.length){const vprior=id==='stgnn'?new Map(crmPredict(fit.crm,normalizeRows(val),rows).map(r=>[r.id,r.prediction])):null;validation=[tf.tensor3d(vs.inputs),tf.tensor2d(vs.targets.map((y,i)=>id==='stgnn'?[normalize(y),normalize(vprior.get(vs.records[i].id)??y)]:[normalize(y)]))];}}}
else if(id==='gdn'){const ins=[],outs=[];for(const rs of Object.values(group(rows)))for(let i=1;i<rs.length;i++){if(day(rs[i])-day(rs[i-1])!==1)continue;ins.push(sensorInput(fit,rs[i-1]));outs.push(scaled(rs[i],features,fit.scale));}if(ins.length<16)throw Error('至少需要16个连续时序转移样本');xs=tf.tensor2d(ins);ys=tf.tensor2d(outs);model.add(tf.layers.dense({inputShape:[10],units:24,activation:'relu'}));model.add(tf.layers.dense({units:16,activation:'relu'}));model.add(tf.layers.dense({units:5}));model.compile({optimizer:tf.train.adam(.003),loss:'meanSquaredError'});}
else if(id==='diagnosis'){fit.classes=[...new Set(rows.flatMap(r=>String(r.root_cause).split('|').map(s=>s.trim()).filter(Boolean)))].sort();if(fit.classes.length<2)throw Error('诊断训练至少需要2种确诊标签');xs=tf.tensor2d(rows.map(r=>scaled(r,fit.keys,fit.scale)));ys=tf.tensor2d(rows.map(r=>fit.classes.map(c=>String(r.root_cause).split('|').map(s=>s.trim()).includes(c)?1:0)));model.add(tf.layers.dense({inputShape:[5],units:24,activation:'relu'}));model.add(tf.layers.dense({units:12,activation:'relu'}));model.add(tf.layers.dense({units:fit.classes.length,activation:'sigmoid'}));model.compile({optimizer:tf.train.adam(.003),loss:'binaryCrossentropy'});if(val.length){validateRows(val,spec.required);if(val.some(r=>String(r.root_cause).split('|').some(c=>!fit.classes.includes(c.trim()))))throw Error('验证集包含训练集中不存在的确诊标签');validation=[tf.tensor2d(val.map(r=>scaled(r,fit.keys,fit.scale))),tf.tensor2d(val.map(r=>fit.classes.map(c=>String(r.root_cause).split('|').map(s=>s.trim()).includes(c)?1:0)))];}}
else if(id==='pinn'){if(rows.some(r=>r.x<0||r.x>1||r.t<0||r.t>1))throw Error('PINN的x、t须归一化到0–1');xs=tf.tensor2d(rows.map(r=>[r.x,r.t]));ys=tf.tensor2d(rows.map(r=>[(r.pressure-fit.yScale.m)/fit.yScale.s]));model.add(tf.layers.dense({inputShape:[2],units:16,activation:'tanh'}));model.add(tf.layers.dense({units:16,activation:'tanh'}));model.add(tf.layers.dense({units:1}));fit.alpha=Number(options.alpha??.02);fit.lambda=Number(options.lambda??.1);const optimizer=tf.train.adam(.003),h=.02;const inside=rows.filter(r=>r.x>=h&&r.x<=1-h&&r.t>=h&&r.t<=1-h);if(!inside.length)throw Error('PINN至少需要一个距时空边界0.02以上的内部点');const coll=tf.tensor2d(inside.map(r=>[r.x,r.t]));for(let epoch=0;epoch<epochs;epoch++){const loss=optimizer.minimize(()=>tf.tidy(()=>{const u=model.apply(coll),xp=model.apply(coll.add(tf.tensor2d([[h,0]]))),xm=model.apply(coll.add(tf.tensor2d([[-h,0]]))),tp=model.apply(coll.add(tf.tensor2d([[0,h]]))),tm=model.apply(coll.add(tf.tensor2d([[0,-h]])));const res=tp.sub(tm).div(2*h).sub(xp.add(xm).sub(u.mul(2)).div(h*h).mul(fit.alpha));return model.apply(xs).sub(ys).square().mean().add(res.square().mean().mul(fit.lambda));}),true);const l=(await loss.data())[0];fit.history.push({epoch:epoch+1,loss:l});progress(epoch+1,epochs,l);loss.dispose();await tf.nextFrame();}coll.dispose();optimizer.dispose();}
fit.network=model;
if(id!=='pinn')await model.fit(xs,ys,{epochs,batchSize:Math.min(32,xs.shape[0]),shuffle:false,validationData:validation,callbacks:{onEpochEnd:async(e,logs)=>{fit.history.push({epoch:e+1,...logs});progress(e+1,epochs,logs.loss);await tf.nextFrame();}}});xs.dispose();ys.dispose();validation?.forEach(t=>t.dispose());
if(id==='gdn'){const scores=await predictModel(fit,rows,true);fit.threshold=quantile(scores.map(x=>x.score),.99)||1e-6;}}
fit.duration=(performance.now()-start)/1000;fit.createdAt=new Date().toISOString();progress(1,1,fit.history.at(-1)?.loss??0);return fit;}
function crmPredict(params,rows,history=[]){const out=[];for(const [w,rs]of Object.entries(group(rows))){const p=params[w];if(!p)throw Error(`井${w}未参与训练，不能使用该井拟合参数`);const merged=new Map([...history.filter(r=>r.well_id===w),...rs].map(r=>[r.date,r]));const all=[...merged.values()].sort((a,b)=>String(a.date).localeCompare(String(b.date)));const xs=crmFeatures(all,p.tau,p.origin),pm=new Map(all.map((r,i)=>[r.date,p.f*xs[i][0]+p.q0*xs[i][1]]));out.push(...rs.map(r=>({...r,prediction:pm.get(r.date),actual:r.liquid})));}return out;}
export async function predictModel(fit,rows,calibration=false){rows=normalizeRows(rows);const spec=MODELS.find(m=>m.id===fit.id),required=inferenceRequired(fit.id);validateRows(rows,required);if(fit.id==='rules'){rows=ordered(rows);const alerts=ruleScan(rows,fit.params),keys=new Set(alerts.map(r=>r.well_id+'@'+r.date));const sums={};return rows.map(r=>{const z=(r.pressure-fit.params.mu)/fit.params.sigma;const k=r.well_id??'W';sums[k]=Math.max(0,(sums[k]??0)+Math.abs(z)-.5);return {...r,prediction:keys.has(r.well_id+'@'+r.date)||sums[k]>5?1:0,score:sums[k]};});}if(fit.id==='arps')return rows.map(r=>{const p=fit.params[r.well_id];if(!p)throw Error(`井${r.well_id}没有训练参数`);return {...r,prediction:arpsPred(p,r),actual:r.oil};});if(fit.id==='crm')return crmPredict(fit.params,rows,fit.trainRows);
const tf=globalThis.tf;let data,records=rows;
if(['tcn','stgnn'].includes(fit.id)){const seq=sequences(fit,rows);if(!seq.inputs.length)throw Error('本批数据不足以构造连续8天历史窗口');data=tf.tensor3d(seq.inputs);records=seq.records;}
else if(fit.id==='gdn'){data=[];records=[];for(const rs of Object.values(group(rows)))for(let i=1;i<rs.length;i++){if(day(rs[i])-day(rs[i-1])!==1)continue;data.push(sensorInput(fit,rs[i-1]));records.push(rs[i]);}if(!data.length)throw Error('没有连续日数据用于图残差预测');data=tf.tensor2d(data);}
else data=tf.tensor2d(rows.map(r=>fit.id==='pinn'?[Number(r.x),Number(r.t)]:scaled(r,fit.keys,fit.scale)));
const tensor=fit.network.predict(data),values=await tensor.array();tensor.dispose();data.dispose();return records.map((r,i)=>{if(fit.id==='gdn'){const x=scaled(r,features,fit.scale),res=x.map((v,j)=>Math.abs(v-values[i][j])),score=mean(res);return {...r,score,prediction:score>(fit.threshold??Infinity)?1:0,driver:features[res.indexOf(Math.max(...res))]};}if(fit.id==='diagnosis'){const labels=fit.classes.filter((c,j)=>values[i][j]>=.5);return {...r,prediction:labels.join('|')||'未达阈值',probabilities:Object.fromEntries(fit.classes.map((c,j)=>[c,values[i][j]]))};}return {...r,prediction:values[i][0]*fit.yScale.s+fit.yScale.m,actual:r[fit.target]};});}
export function evaluate(fit,results){if(['rules','gdn'].includes(fit.id)){const a=results.filter(r=>finite(r.label)&&[0,1].includes(Number(r.label)));return classificationMetrics(a.map(r=>Number(r.label)),a.map(r=>r.prediction));}if(fit.id==='diagnosis'){const a=results.filter(r=>r.root_cause);if(!a.length)return null;if(a.some(r=>String(r.root_cause).split('|').some(c=>!fit.classes.includes(c.trim()))))throw Error('评价集中存在训练未见的确诊标签，无法按已知类别计算指标');return classificationMetrics(a.flatMap(r=>fit.classes.map(c=>String(r.root_cause).split('|').map(s=>s.trim()).includes(c)?1:0)),a.flatMap(r=>fit.classes.map(c=>String(r.prediction).split('|').includes(c)?1:0)));}return regressionMetrics(results.map(r=>r.actual),results.map(r=>r.prediction));}
export async function exportFit(fit){const meta={id:fit.id,target:fit.target,params:fit.params,keys:fit.keys,crm:fit.crm,scale:fit.scale,yScale:fit.yScale,classes:fit.classes,graph:fit.graph,threshold:fit.threshold,duration:fit.duration,createdAt:fit.createdAt,trainedRows:fit.trainedRows,history:fit.history,alpha:fit.alpha,lambda:fit.lambda};if(fit.network){await fit.network.save({save:async a=>{meta.modelTopology=a.modelTopology;meta.weightSpecs=a.weightSpecs;meta.weightData=Array.from(new Uint8Array(a.weightData));return {modelArtifactsInfo:{dateSaved:new Date(),modelTopologyType:'JSON'}};}});}return meta;}
